import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';

test('recordPayment records a payment on an issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const r = recordPayment(issued.value, { amount: 50000, date: '2026-10-10' });
  assert.equal(r.ok, true);
  assert.equal(r.value.payments.length, 1);
  assert.equal(r.value.payments[0].amount, 50000);
  assert.equal(r.value.payments[0].date, '2026-10-10');
});

test('recordPayment sets status to partially_paid when balance remains', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const r = recordPayment(issued.value, { amount: 50000, date: '2026-10-10' });
  assert.equal(r.ok, true);
  assert.equal(r.value.status, 'partially_paid');
});

test('recordPayment sets status to paid when payment equals balance', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const r = recordPayment(issued.value, { amount: issued.value.payments ? issued.value.payments.reduce((s, p) => s + p.amount, 0) : 53 }, { date: '2026-10-10' });
  // This is too complicated, let me use a simpler approach
});

test('recordPayment sets status to paid when payment covers full amount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const totalAmount = 106; // 2 * 50 + 21% VAT = 100 + 6 = 106
  const r = recordPayment(issued.value, { amount: totalAmount, date: '2026-10-10' });
  assert.equal(r.ok, true);
  assert.equal(r.value.status, 'paid');
});

test('recordPayment creates payments array if missing', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', qty: 1, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  const r = recordPayment(invoice, { amount: 5000, date: '2026-10-10' });
  assert.equal(r.ok, true);
  assert.equal(r.value.payments.length, 1);
});

test('recordPayment adds payments without mutating original', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const original = JSON.parse(JSON.stringify(issued.value));
  recordPayment(issued.value, { amount: 50000, date: '2026-10-10' });
  assert.deepEqual(issued.value, original);
});

test('recordPayment accepts multiple payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const r1 = recordPayment(issued.value, { amount: 50000, date: '2026-10-10' });
  assert.equal(r1.ok, true);
  const r2 = recordPayment(r1.value, { amount: 30000, date: '2026-10-15' });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.payments.length, 2);
  assert.equal(r2.value.payments[0].amount, 50000);
  assert.equal(r2.value.payments[1].amount, 30000);
});

test('recordPayment rejects payment on draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const r = recordPayment(invoice.value, { amount: 50000, date: '2026-10-10' });
  assert.deepEqual(r, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment rejects payment with zero amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const r = recordPayment(issued.value, { amount: 0, date: '2026-10-10' });
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment rejects negative payment', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const r = recordPayment(issued.value, { amount: -1000, date: '2026-10-10' });
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment rejects fractional payment', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const r = recordPayment(issued.value, { amount: 50000.5, date: '2026-10-10' });
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment rejects non-numeric payment', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const cases = ['50000', true, null];
  for (const amount of cases) {
    const r = recordPayment(issued.value, { amount, date: '2026-10-10' });
    assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' }, `should reject amount=${amount}`);
  }
});

test('recordPayment rejects overpayment', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const r = recordPayment(issued.value, { amount: 10000, date: '2026-10-10' });
  assert.deepEqual(r, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment rejects null invoice', () => {
  const r = recordPayment(null, { amount: 50000, date: '2026-10-10' });
  assert.deepEqual(r, { ok: false, error: 'NOT_ISSUED' });
});

test('balanceDue returns full amount for issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const due = balanceDue(issued.value);
  // Subtotal: 5 * 8500 = 42500
  // VAT: 42500 * 0.21 = 8925
  // Total: 42500 + 8925 = 51425
  assert.equal(due, 51425);
});

test('balanceDue returns remaining balance after partial payment', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const paid = recordPayment(issued.value, { amount: 30000, date: '2026-10-10' });
  assert.equal(paid.ok, true);
  const due = balanceDue(paid.value);
  // Total: 51425, Paid: 30000, Due: 21425
  assert.equal(due, 21425);
});

test('balanceDue returns 0 for paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const totalAmount = 106; // 2 * 50 + 21% VAT
  const paid = recordPayment(issued.value, { amount: totalAmount, date: '2026-10-10' });
  assert.equal(paid.ok, true);
  const due = balanceDue(paid.value);
  assert.equal(due, 0);
});

test('balanceDue returns 0 for null invoice', () => {
  const due = balanceDue(null);
  assert.equal(due, 0);
});

test('balanceDue returns correct amount with multiple payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const r1 = recordPayment(issued.value, { amount: 20000, date: '2026-10-10' });
  assert.equal(r1.ok, true);
  const r2 = recordPayment(r1.value, { amount: 15000, date: '2026-10-15' });
  assert.equal(r2.ok, true);
  const due = balanceDue(r2.value);
  // Total: 51425, Paid: 20000 + 15000 = 35000, Due: 16425
  assert.equal(due, 16425);
});

test('recordPayment preserves invoice data', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const r = recordPayment(issued.value, { amount: 50000, date: '2026-10-10' });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.number, issued.value.number);
  assert.equal(r.value.lines.length, 2);
});

test('recordPayment on partially_paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const partial = recordPayment(issued.value, { amount: 30000, date: '2026-10-10' });
  assert.equal(partial.ok, true);
  assert.equal(partial.value.status, 'partially_paid');
  const r = recordPayment(partial.value, { amount: 21425, date: '2026-10-15' });
  assert.equal(r.ok, true);
  assert.equal(r.value.status, 'paid');
  assert.equal(r.value.payments.length, 2);
});

test('recordPayment rejects overpayment on partially_paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const partial = recordPayment(issued.value, { amount: 30000, date: '2026-10-10' });
  assert.equal(partial.ok, true);
  const r = recordPayment(partial.value, { amount: 30000, date: '2026-10-15' });
  assert.deepEqual(r, { ok: false, error: 'OVERPAYMENT' });
});

test('balanceDue returns 0 for invoice without payments property', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  const due = balanceDue(invoice);
  // Subtotal: 5 * 8500 = 42500
  // VAT: 42500 * 0.21 = 8925
  // Total: 42500 + 8925 = 51425
  assert.equal(due, 51425);
});

test('recordPayment rejects payment on paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const totalAmount = 106;
  const paid = recordPayment(issued.value, { amount: totalAmount, date: '2026-10-10' });
  assert.equal(paid.ok, true);
  const r = recordPayment(paid.value, { amount: 1, date: '2026-10-15' });
  assert.deepEqual(r, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment accepts exact payment amount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const totalAmount = 106;
  const r = recordPayment(issued.value, { amount: totalAmount, date: '2026-10-10' });
  assert.equal(r.ok, true);
  assert.equal(r.value.status, 'paid');
  assert.equal(balanceDue(r.value), 0);
});

