    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const r = recordPayment(issued.value, { amount: 10000, date: '2026-10-10' });
  assert.deepEqual(r, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment rejects null invoice', () => {
  const r = recordPayment(null, { amount: 50000, date: '2026-10-10' });
  assert.deepEqual(r, { ok: false, error: 'NOT_ISSUED' });
});

test('balanceDue returns full amount for issued invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const totals = invoiceTotals(issued.value);
  assert.equal(totals.ok, true);
  const due = balanceDue(issued.value);
  assert.equal(due, totals.value.total);
});

test('balanceDue returns remaining balance after partial payment', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);
  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);
  const totals = invoiceTotals(issued.value);
  assert.equal(totals.ok, true);
  const paid = recordPayment(issued.value, { amount: 30000, date: '2026-10-10' });
  assert.equal(paid.ok, true);
  const due = balanceDue(paid.value);
